(function (global) {
    function escapeHtml(value) {
        return String(value == null ? '' : value).replace(/[&<>"']/g, function (char) {
            return ({
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
            })[char];
        });
    }

    function escapeAttribute(value) {
        return escapeHtml(value).replace(/`/g, '&#96;');
    }

    function safeUrl(value) {
        var url = String(value || '').trim();
        if (/^(https?:|mailto:|\/)/i.test(url)) return url;
        return '#';
    }

    function renderInline(value) {
        var text = escapeHtml(value);
        text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
        text = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        text = text.replace(/__([^_]+)__/g, '<strong>$1</strong>');
        text = text.replace(/\*([^*]+)\*/g, '<em>$1</em>');
        text = text.replace(/_([^_]+)_/g, '<em>$1</em>');
        text = text.replace(/\[([^\]]+)\]\(([^)\s]+)(?:\s+"([^"]*)")?\)/g, function (_, label, href, title) {
            var attr = ' href="' + escapeAttribute(safeUrl(href)) + '"';
            if (title) attr += ' title="' + escapeAttribute(title) + '"';
            return '<a' + attr + '>' + label + '</a>';
        });
        return text;
    }

    function flushParagraph(lines, output) {
        if (!lines.length) return;
        output.push('<p>' + renderInline(lines.join(' ')) + '</p>');
        lines.length = 0;
    }

    function toHTML(markdownText) {
        var source = String(markdownText == null ? '' : markdownText).replace(/\r\n?/g, '\n');
        var lines = source.split('\n');
        var output = [];
        var paragraph = [];
        var inCode = false;
        var codeLines = [];

        for (var i = 0; i < lines.length; i++) {
            var line = lines[i];
            if (/^```/.test(line)) {
                if (inCode) {
                    output.push('<pre><code>' + escapeHtml(codeLines.join('\n')) + '</code></pre>');
                    codeLines = [];
                    inCode = false;
                } else {
                    flushParagraph(paragraph, output);
                    inCode = true;
                }
                continue;
            }
            if (inCode) {
                codeLines.push(line);
                continue;
            }
            if (!line.trim()) {
                flushParagraph(paragraph, output);
                continue;
            }
            var heading = line.match(/^(#{1,6})\s+(.+)$/);
            if (heading) {
                flushParagraph(paragraph, output);
                output.push('<h' + heading[1].length + '>' + renderInline(heading[2]) + '</h' + heading[1].length + '>');
                continue;
            }
            var quote = line.match(/^>\s?(.*)$/);
            if (quote) {
                flushParagraph(paragraph, output);
                output.push('<blockquote><p>' + renderInline(quote[1]) + '</p></blockquote>');
                continue;
            }
            paragraph.push(line.trim());
        }
        if (inCode) output.push('<pre><code>' + escapeHtml(codeLines.join('\n')) + '</code></pre>');
        flushParagraph(paragraph, output);
        return output.join('\n');
    }

    global.markdown = global.markdown || {};
    global.markdown.toHTML = toHTML;
}(window));
